  "PAPAL ARMS BAN AGAINST {0}: OBSERVED BY {1}": "PAPIESKIE EMBARGO NA BROŃ PRZECIW {0}: PRZESTRZEGANE PRZEZ {1}",
  "PAPAL ARMS BAN AGAINST {0}: OBSERVED BY {1} POLITIES": "PAPIESKIE EMBARGO NA BROŃ PRZECIW {0}: PRZESTRZEGA GO {1} PAŃSTW",
  "Papal Commendation": "Pochwała papieska",
  "PAPAL GRAIN ALMS UNDERWAY FOR {0}": "TRWA JAŁMUŻNA PAPIESKA DLA {0}",
